test("review assignment scenario 1", { tag: '@functionality' }, async ({ browser }) => {
  const sheet = ui.sheetId();
  const pg_uma = await ui.userPage(browser, "uma", sheet);
  await ui.setToday(pg_uma, "2026-03-20");
  await ui.setSetting(pg_uma, "late-pct", "10.00");
  await ui.setSetting(pg_uma, "policy-date", "2026-03-15");
  await ui.setSetting(pg_uma, "terms-B", "20");
  await ui.setSetting(pg_uma, "cap", "5.00");
  await ui.setSetting(pg_uma, "entry-date", "2026-03-05");
  expect(await ui.addVoidReason(pg_uma, "dup")).toBe(true);
  await ui.loadSheet(pg_uma, `${sheet}-p`);
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "5.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "7.50"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "20.00"})).toBe(true);
  const p_ben = ui.must(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "A"}));
  const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "C"}));
  await ui.loadSheet(pg_uma, sheet);
  await ui.setSetting(pg_uma, "parent", `${sheet}-p`);
  expect(await ui.setSettingDated(pg_uma, "rounding", "half-up", "2026-03-01", "half-up")).toBe(true);
  await ui.setSetting(pg_uma, "review-sla", "1");
  await ui.setSetting(pg_uma, "escalate-after", "7");
  await ui.setSetting(pg_uma, "clerk-limit-B", "0.50");
  await ui.setSetting(pg_uma, "score-mid", "0");
  await ui.setSetting(pg_uma, "score-high", "5");
  await ui.setSetting(pg_uma, "max-open", "3");
  expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "33.33"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "10.00"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "C", "pct": "33.33"})).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "7.50", "from": "2026-03-10", "to": "2026-03-12"})).toBe(true);
  expect(await ui.generatePeriods(pg_uma, "2026-02-01", "2026-04-30")).toBe(3);
  expect(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "B", "terms": "3", "tags": "a"})).toBeNull();
  expect(await ui.addPerson(pg_uma, {"name": "Ben", "grade": "A", "contact": "ben@x"})).toBeNull();
  const p_cam = ui.must(await ui.addPerson(pg_uma, {"name": "Cam", "grade": "B"}));
  expect(await ui.editPerson(pg_uma, p_cam, {"terms": "20", "termsFrom": "2026-03-12"})).toBe(true);
  const pl_cam_1 = ui.must(await ui.addPlan(pg_uma, p_cam, {"amount": "99.95", "start": "2026-03-09", "end": "2026-04-30", "day": "31"}));
  expect(await ui.inlineGrade(pg_uma, p_cam, "C")).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "12.50"})).toBe(true);
  expect(await ui.importOpenings(pg_uma, "Cam,2026-03,1.00")).toBe(1);
  expect(await ui.planAmount(pg_uma, pl_cam_1, "10.35")).toBe(true);
  expect(await ui.planAmount(pg_uma, pl_cam_1, "12.50")).toBe(true);
  expect(await ui.hold(pg_uma, p_cam, {"from": "2026-02-25", "to": "2026-03-20"})).toBe(true);
  expect(await ui.periodAction(pg_uma, "2026-04", "soft-close")).toBe(true);
  await ui.refresh(pg_uma);
  const c_cam_0 = ui.must(await ui.addClaimTwice(pg_uma, p_cam, {"amount": "0.40", "date": "2026-03-09"}));
  expect(await ui.claimCount(pg_uma, p_cam)).toBe(1);
  expect(await ui.ratePreview(pg_uma, "A", "33.33")).toEqual({ count: 0, diff: "0.00" });
  expect(await ui.addProof(pg_uma, c_cam_0, "photo")).toBe(true);
  expect(await ui.editClaim(pg_uma, c_cam_0, {"amount": "7.77"})).toBe(true);
  expect(await ui.editClaim(pg_uma, c_cam_0, {"amount": "10.35"})).toBe(true);
  expect(await ui.editInline(pg_uma, c_cam_0, "12.50")).toBe(true);
  expect(await ui.ratePreview(pg_uma, "B", "10.00")).toEqual({ count: 0, diff: "0.00" });
  await ui.refresh(pg_uma);
  expect(await ui.editPerson(pg_uma, p_cam, {"grade": "B", "gradeFrom": "2026-03-20"})).toBe(true);
  expect(await ui.claimAction(pg_uma, c_cam_0, "void")).toBe(false);
  expect(await ui.statement(pg_uma, p_cam)).toBe(true);
  expect(await ui.ratePreview(pg_uma, "C", "5.00")).toEqual({ count: 0, diff: "0.00" });
  expect(await ui.hold(pg_uma, p_cam, {"from": "2026-03-09"})).toBe(true);
  expect(await ui.claimAction(pg_uma, c_cam_0, "open")).toBe(true);
  expect(await ui.setRate(pg_uma, {"grade": "B", "pct": "5.00", "from": "2026-04-04"})).toBe(true);
  await ui.refresh(pg_uma);
  const pg_vic = await ui.userPage(browser, "vic", sheet);
  expect(await ui.claimAction(pg_vic, c_cam_0, "settle", "2026-02-10")).toBe(false);
  await ui.setAsOf(pg_vic, "2026-03-20");
  await ui.refresh(pg_vic);

